from django.urls import include, path
from rest_framework.routers import DefaultRouter

from .dashboard_views import (
    DashboardSummaryView,
    SalesByCategoryView,
    SalesByMonthView,
    TopClientsView,
)
from .views import CSVUploadStatusView, CSVUploadView, OrderViewSet

# The router handles the ViewSets (CRUD)
router = DefaultRouter()
router.register(r"orders", OrderViewSet, basename="order")

# urlpatterns combines the router routes with the custom routes
urlpatterns = [
    # includes every route generated by the router (/orders/, /orders/<id>/)
    path("", include(router.urls)),
    # explicit manual route for the upload (it is an APIView)
    path("upload-csv/", CSVUploadView.as_view(), name="upload-csv"),
    # route that checks the upload status by its UUID
    path(
        "upload-csv/<uuid:pk>/status/",
        CSVUploadStatusView.as_view(),
        name="upload-csv-status",
    ),
    # dashboard aggregations (summary, by month, by category, top clients)
    path(
        "dashboard/summary/",
        DashboardSummaryView.as_view(),
        name="dashboard-summary",
    ),
    path(
        "dashboard/sales-by-month/",
        SalesByMonthView.as_view(),
        name="dashboard-sales-by-month",
    ),
    path(
        "dashboard/sales-by-category/",
        SalesByCategoryView.as_view(),
        name="dashboard-sales-by-category",
    ),
    path(
        "dashboard/top-clients/",
        TopClientsView.as_view(),
        name="dashboard-top-clients",
    ),
]
